init_logger();
import fs8 from "fs";

// src/helpers/instructionParser.ts
class InstructionParser {
  static parseBlock(content) {
    const blocks = [];
    const lines = content.split(`
`).map((line) => line.trim()).filter((line) => line.length > 0);
    let currentBlock = null;
    let braceLevel = 0;
    for (const line of lines) {
      if (line.includes("{")) {
        if (currentBlock === null) {
          const blockName = line.replace("{", "").trim();
          currentBlock = {
            type: "block",
            name: blockName,
            instructions: [],
            variables: [],
            blocks: []
          };
        }
        braceLevel++;
      } else if (line.includes("}")) {
        braceLevel--;
        if (braceLevel === 0 && currentBlock) {
          blocks.push(currentBlock);
          currentBlock = null;
        }
      } else if (currentBlock && braceLevel === 1) {
        if (line.includes("(") && line.includes(")")) {
          const instruction = this.parseInstruction(line);
          if (instruction) {
            currentBlock.instructions.push(instruction);
          }
        } else if (line.includes("=")) {
          const variable = this.parseVariable(line);
          if (variable) {
            currentBlock.variables.push(variable);
          }
        }
      }
    }
    return blocks;
  }
  static parseInstruction(line) {
    const match = line.match(/(\w+)\s*\((.*?)\)/);
    if (!match)
      return null;
    const name = match[1];
    const paramString = match[2];
    const parameters = paramString.split(",").map((p) => p.trim().replace(/['"]/g, ""));
    return { name, parameters };
  }
  static parseVariable(line) {
    const parts = line.split("=");
    if (parts.length !== 2)
      return null;
    const name = parts[0].trim();
    const valueStr = parts[1].trim();
    let value = valueStr;
    if (!isNaN(Number(valueStr))) {
      value = Number(valueStr);
    }
    return { name, value };
  }
}

// src/helpers/includeFile.ts
class IncludeFile {
  logger;
  content;
  blocks = new Map;
  statements = [];
  constructor(filePath, _separators = "([(){}=,;\\n\\r\\t ])") {
    this.logger = new Logger("IncludeFile");
    if (!fs8.existsSync(filePath)) {
      throw new Error(`File not found: ${filePath}`);
    }
    this.content = fs8.readFileSync(filePath, "utf-8");
    this.parseContent();
  }
  parseContent() {
    this.statements = InstructionParser.parseBlock(this.content);
    for (const statement of this.statements) {
      const block = {
        name: statement.name,
        unknownStatements: [],
        getInstruction: (name) => {
          return statement.instructions.find((i2) => i2.name === name) || null;
        },
        getInstructions: (name) => {
          return statement.instructions.filter((i2) => i2.name === name);
        },
        getVariable: (name) => {
          return statement.variables.find((v) => v.name === name) || null;
        }
      };
      this.blocks.set(statement.name, block);
    }
  }
  get Statements() {
    return this.statements;
  }
  getBlock(blockName) {
    return this.blocks.get(blockName) || null;
  }
  dispose() {
    this.blocks.clear();
    this.statements = [];
  }
}

