// src/abstract/wldFile.ts
class WldFile {
  static DefaultMPU = 4;
  worldData;
  constructor(filePath) {
    this.read(filePath);
  }
  read(filePath) {
    try {
      const data = fs14.readFileSync(filePath, "utf-8");
      const lines = data.split(`
`);
      let size = null;
      let isIndoor = false;
      let canFly = false;
      let mpu = WldFile.DefaultMPU;
      let revivalMapId = 0;
      let revivalKey = "";
      for (const lineContent of lines) {
        const line = lineContent.trim().toLowerCase();
        if (!line || line.startsWith("//")) {
          continue;
        }
        const lineArray = line.split(" ");
        switch (lineArray[0].toLowerCase()) {
          case "size":
            size = this.readSize(lineArray);
            break;
          case "indoor":
            isIndoor = lineArray[1] === "1";
            break;
          case "fly":
            canFly = lineArray[1] === "1";
            break;
          case "mpu":
            mpu = parseInt(lineArray[1]);
            break;
          case "revival":
            revivalMapId = parseInt(lineArray[1]);
            revivalKey = lineArray[2].replace(/"/g, "");
            break;
        }
      }
      if (!size) {
        return;
      }
      this.worldData = {
        width: size.x,
        length: size.z,
        mpu,
        indoor: isIndoor,
        fly: canFly,
        revivalMapId,
        revivalKey
      };
    } catch (error) {
      console.error("Error reading file:", error);
    }
  }
  readSize(lineArray) {
    const width = lineArray[1].replace(",", "");
    const length = lineArray[2];
    return new Vector3(parseInt(width), 0, parseInt(length));
  }
}

