// src/abstract/rgn/rgnFile.ts
class RgnFile {
  filePath;
  _elements = [];
  get Elements() {
    return this._elements;
  }
  constructor(filePath) {
    this.filePath = filePath;
    this.read();
  }
  read() {
    try {
      const fileContent = fs15.readFileSync(this.filePath, "utf16le");
      const lines = fileContent.split(`
`);
      for (const line of lines) {
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith("//")) {
          continue;
        }
        const data = trimmedLine.split(/\s+/);
        if (trimmedLine.startsWith("respawn7")) {
          if (data.length < 24) {
            continue;
          }
          this._elements.push(new RgnRespawn7(data));
        } else if (trimmedLine.startsWith("region3")) {
          if (data.length < 32) {
            continue;
          }
          this._elements.push(new RgnRegion3(data));
        }
      }
    } catch (error) {
      console.error("Error reading RgnFile:", error);
    }
  }
  getElements() {
    return this._elements.filter((x) => x);
  }
}

